// Saved-DWG display metadata only; no entity or system-variable writes.
using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Web.Script.Serialization;
using Autodesk.AutoCAD.Runtime;using Autodesk.AutoCAD.DatabaseServices;using Autodesk.AutoCAD.EditorInput;
using App=Autodesk.AutoCAD.ApplicationServices.Core.Application;
public class NativeDisplayStateReadV1 {
 public class Source{public string path,sha256;public string[] handles,layers,layouts;}
 public class Config{public Source[] sources;public string receipt;}
 static readonly JavaScriptSerializer J=new JavaScriptSerializer{MaxJsonLength=50000000};
 static object Transparency(Autodesk.AutoCAD.Colors.Transparency t){return new{text=t.ToString(),alpha=t.IsByAlpha?(int?)t.Alpha:null,by_alpha=t.IsByAlpha,by_layer=t.IsByLayer,by_block=t.IsByBlock};}
 static object Values(ResultBuffer b){if(b==null)return null;using(b)return b.AsArray().Select(x=>new{code=x.TypeCode,value=Convert.ToString(x.Value,System.Globalization.CultureInfo.InvariantCulture)}).ToArray();}
 static object Extension(DBObject o,Transaction tr){var entries=new List<object>();if(!o.ExtensionDictionary.IsNull){var dict=(DBDictionary)tr.GetObject(o.ExtensionDictionary,OpenMode.ForRead);foreach(DBDictionaryEntry item in dict){var value=tr.GetObject(item.Value,OpenMode.ForRead);var rec=value as Xrecord;entries.Add(new{name=item.Key,type=value.GetRXClass().Name,data=rec==null?null:Values(rec.Data)});}}return new{xdata=Values(o.XData),dictionary=entries};}
 static object Pieces(Entity e,int depth){
  var children=new List<object>();string error=null;var parts=new DBObjectCollection();
  try{if(depth<4 && !(e is Curve) && !(e is DBText) && !(e is MText)){e.Explode(parts);foreach(DBObject item in parts){var child=item as Entity;if(child!=null)children.Add(Pieces(child,depth+1));}}}
  catch(System.Exception ex){error=ex.Message;}
  finally{foreach(DBObject item in parts)item.Dispose();}
  return new{type=e.GetRXClass().Name,layer=e.Layer,color=e.Color.ToString(),color_index=e.Color.ColorIndex,color_method=e.Color.ColorMethod.ToString(),transparency=Transparency(e.Transparency),text=e is DBText?((DBText)e).TextString:e is MText?((MText)e).Contents:null,children=children,expand_error=error};
 }
 [CommandMethod("HLCADDISPLAYSTATEREADV1",CommandFlags.Session)]public void Run(){
  var a=App.DocumentManager.MdiActiveDocument.Editor.GetString(new PromptStringOptions("Read saved display metadata:"){AllowSpaces=true});if(a.Status!=PromptStatus.OK)return;Config c=null;
  var active=App.DocumentManager.MdiActiveDocument;var before=App.GetSystemVariable("DBMOD");
  try{c=J.Deserialize<Config>(File.ReadAllText(a.StringResult.Trim('"')));if(File.Exists(c.receipt))throw new InvalidOperationException("RECEIPT_EXISTS");var results=new List<object>();foreach(var s in c.sources){if(NativeGeometryReadV1.Hash(s.path)!=s.sha256)throw new InvalidOperationException("SOURCE_CHANGED");
   using(var db=new Database(false,true)){db.ReadDwgFile(s.path,FileOpenMode.OpenForReadAndAllShare,true,"");db.CloseInput(true);var previous=HostApplicationServices.WorkingDatabase;try{HostApplicationServices.WorkingDatabase=db;using(var tr=db.TransactionManager.StartTransaction()){
    var lt=(LayerTable)tr.GetObject(db.LayerTableId,OpenMode.ForRead);var layers=new List<object>();foreach(var name in s.layers??new string[0]){if(!lt.Has(name)){layers.Add(new{name,missing=true});continue;}var l=(LayerTableRecord)tr.GetObject(lt[name],OpenMode.ForRead);layers.Add(new{name,handle=l.Handle.ToString(),color=l.Color.ToString(),color_method=l.Color.ColorMethod.ToString(),l.IsOff,l.IsFrozen,l.IsLocked,l.IsDependent,l.IsPlottable,transparency=Transparency(l.Transparency),plot_style=l.PlotStyleNameId.Handle.ToString()});}
    var ents=new List<object>();foreach(var h in s.handles??new string[0]){var e=(Entity)tr.GetObject(db.GetObjectId(false,new Handle(Convert.ToInt64(h,16)),0),OpenMode.ForRead);ents.Add(new{handle=h,type=e.GetRXClass().Name,layer=e.Layer,color=e.Color.ToString(),color_method=e.Color.ColorMethod.ToString(),e.Visible,transparency=Transparency(e.Transparency),owner=e.OwnerId.Handle.ToString(),plot_style=e.PlotStyleName,extension=Extension(e,tr),layer_extension=Extension(tr.GetObject(e.LayerId,OpenMode.ForRead),tr),stored_graphics=Pieces(e,0)});}
    var dict=(DBDictionary)tr.GetObject(db.LayoutDictionaryId,OpenMode.ForRead);var layouts=new List<object>();foreach(var name in s.layouts??new string[0]){if(!dict.Contains(name)){layouts.Add(new{name,missing=true});continue;}var l=(Layout)tr.GetObject(dict.GetAt(name),OpenMode.ForRead);var vps=new List<object>();foreach(ObjectId id in l.GetViewports()){var vp=(Viewport)tr.GetObject(id,OpenMode.ForRead);var overrides=new List<object>();foreach(var layerName in s.layers??new string[0]){if(!lt.Has(layerName))continue;var layer=(LayerTableRecord)tr.GetObject(lt[layerName],OpenMode.ForRead);var o=layer.GetViewportOverrides(id);overrides.Add(new{name=layerName,color_overridden=o.IsColorOverridden,color=o.IsColorOverridden?o.Color.ToString():null,color_index=o.IsColorOverridden?(int?)o.Color.ColorIndex:null,transparency_overridden=o.IsTransparencyOverridden,transparency=o.IsTransparencyOverridden?Transparency(o.Transparency):null,plot_style_overridden=o.IsPlotStyleOverridden,plot_style=o.IsPlotStyleOverridden?o.PlotStyleName:null});}vps.Add(new{handle=vp.Handle.ToString(),number=vp.Number,overrides=overrides});}layouts.Add(new{name,l.ShowPlotStyles,l.CurrentStyleSheet,l.PlotPlotStyles,viewports=vps});}
    results.Add(new{path=s.path,sha256=s.sha256,entities=ents,layers,layouts});
   }}finally{HostApplicationServices.WorkingDatabase=previous;}}if(NativeGeometryReadV1.Hash(s.path)!=s.sha256)throw new InvalidOperationException("SOURCE_CHANGED_DURING_READ");
  }var after=App.GetSystemVariable("DBMOD");if(active!=App.DocumentManager.MdiActiveDocument||!Equals(before,after))throw new InvalidOperationException("ACTIVE_DOCUMENT_CHANGED_DURING_READ");File.WriteAllText(c.receipt,J.Serialize(new{status="SAVED_DISPLAY_STATE_READ",read_only=true,host_image=System.Diagnostics.Process.GetCurrentProcess().MainModule.FileName,dbmod_before=before,dbmod_after=after,sources=results}));
 }catch(System.Exception e){if(c!=null&&!File.Exists(c.receipt))File.WriteAllText(c.receipt,J.Serialize(new{status="DISPLAY_STATE_READ_FAILED",error=e.ToString()}));}}
}
